package scenevalidation
import ("crypto/sha256";"encoding/hex";"encoding/json";"errors";"fmt";"os";"path/filepath";"strings")
type Bounds struct{X float64 `json:"x"`; Y float64 `json:"y"`; Width float64 `json:"width"`; Height float64 `json:"height"`}
type Element struct{Layer string `json:"layer"`; ID string `json:"id"`; Bounds Bounds `json:"bounds"`; Z int `json:"z_index"`; Component string `json:"component_type"`; Tokens []string `json:"design_tokens"`; Links []string `json:"semantic_link"`; Content string `json:"content"`; Asset string `json:"asset_reference"`; AssetSHA *string `json:"asset_sha256"`; SourceRef string `json:"source_reference"`}
type Origin struct{Path string `json:"path"`;SHA *string `json:"sha256"`}
type Manifest struct{ID string `json:"manifest_id"`;Reference Origin `json:"reference"`;Source Origin `json:"source"`;Canvas struct{Width float64 `json:"width"`;Height float64 `json:"height"`} `json:"canvas"`;Elements []Element `json:"elements"`}
var tokens=map[string]bool{"ink-primary":true,"ink-muted":true,"stroke-1":true,"stroke-2":true,"alert-orange":true}
var components=map[string]bool{"horizontal-rule":true,"vertical-rule":true,"container-box":true,"connector-arrow":true,"verification-diamond":true}
func ValidateBounds(m Manifest)error{if m.Canvas.Width!=1600||m.Canvas.Height!=900{return errors.New("CANVAS_INVALID")};for _,e:=range m.Elements{b:=e.Bounds;if b.X<0||b.Y<0||b.Width<=0||b.Height<=0||b.X+b.Width>m.Canvas.Width||b.Y+b.Height>m.Canvas.Height{return fmt.Errorf("BOUNDS_INVALID:%s",e.ID)}};return nil}
func ValidateTokens(m Manifest)error{for _,e:=range m.Elements{for _,t:=range e.Tokens{if !tokens[t]{return fmt.Errorf("TOKEN_UNAPPROVED:%s:%s",e.ID,t)}};if e.Layer=="art"&&!components[e.Component]{return fmt.Errorf("COMPONENT_UNAPPROVED:%s",e.ID)};if strings.Contains(strings.ToLower(e.Content),"<svg")||strings.HasSuffix(strings.ToLower(e.Asset),".svg"){return fmt.Errorf("SVG_FORBIDDEN:%s",e.ID)}};return nil}
func ValidateLinks(m Manifest)error{ids:=map[string]bool{};for _,e:=range m.Elements{if e.ID==""||ids[e.ID]{return fmt.Errorf("ID_INVALID:%s",e.ID)};ids[e.ID]=true};for _,e:=range m.Elements{for _,l:=range e.Links{if !ids[l]{return fmt.Errorf("LINK_ORPHAN:%s:%s",e.ID,l)}}};return nil}
func ValidateLayers(m Manifest)error{for _,e:=range m.Elements{switch e.Layer{case "story":if e.Z<0||e.Z>9{return fmt.Errorf("STORY_Z_INVALID:%s",e.ID)};case "art":if e.Z<10||e.Z>19{return fmt.Errorf("ART_Z_INVALID:%s",e.ID)};case "text":if e.Z<20||e.Z>29{return fmt.Errorf("TEXT_Z_INVALID:%s",e.ID)};default:return fmt.Errorf("LAYER_INVALID:%s",e.ID)}};return nil}
func checkOrigin(o Origin)error{if o.Path==""||o.SHA==nil{return errors.New("PROVENANCE_NOT_ESTABLISHED")};if filepath.Base(o.Path)!=o.Path{return errors.New("PROVENANCE_PATH_UNSAFE")};b,e:=os.ReadFile(o.Path);if e!=nil{return e};h:=sha256.Sum256(b);if hex.EncodeToString(h[:])!=*o.SHA{return errors.New("PROVENANCE_HASH_MISMATCH")};return nil}
func ValidateProvenance(m Manifest)error{if e:=checkOrigin(m.Reference);e!=nil{return fmt.Errorf("REFERENCE:%w",e)};if e:=checkOrigin(m.Source);e!=nil{return fmt.Errorf("SOURCE:%w",e)};return nil}
func Validate(m Manifest)error{for _,f:=range []func(Manifest)error{ValidateBounds,ValidateLayers,ValidateTokens,ValidateLinks,ValidateProvenance}{if err:=f(m);err!=nil{return err}};return nil}
func Load(path string)(Manifest,error){var m Manifest;b,e:=os.ReadFile(path);if e!=nil{return m,e};e=json.Unmarshal(b,&m);return m,e}
